import * as THREE from 'three/webgpu';
import { NodeMaterial, AttributeNode } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {{hero:string,subhead:string,caption:string}} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{[key:string]:(target:THREE.Object3D,params:any)=>void}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{textureLoader: (url:string)=>THREE.Texture}} textureLoader
 * @property {{glbLoader:any}} glbLoader
 */

/**
 * Create the particle constellation hero node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Apply transform from config
  if (config.position) root.position.set(config.position.x, config.position.y, config.position.z);
  if (config.rotation) root.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  if (config.scale) root.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // ---------- TEXT ----------
  const textGroup = new THREE.Group();

  // Helper to create a text mesh via the fontAtlas (MSDF)
  const createTextMesh = (text, size, colorHex) => {
    // Assume ctx.fontAtlas.createText returns a THREE.Mesh with proper material
    const mesh = ctx.fontAtlas.createText(text, {
      size,
      color: new THREE.Color(colorHex),
      // alignment centre by default
    });
    return mesh;
  };

  // Hero
  const heroMesh = createTextMesh(
    config.textContent?.hero || 'NOVA ATELIER',
    124, // raw pixel size, will be interpreted by the atlas
    '#16161d' // ink
  );
  heroMesh.position.set(0, 0.5, 0.5);
  textGroup.add(heroMesh);

  // Subhead
  const subheadMesh = createTextMesh(
    config.textContent?.subhead || 'Precision instruments for the dark hours.',
    40,
    '#e8ecf2' // paper
  );
  subheadMesh.position.set(0, -0.25, 0.5); // 0.75 below hero baseline (0.5 - 0.75)
  textGroup.add(subheadMesh);

  // Caption
  const captionMesh = createTextMesh(
    config.textContent?.caption || 'EST. 2019 / GENEVA AND KYOTO',
    18,
    '#e8ecf2' // paper
  );
  captionMesh.position.set(0, -2.25, 0.5);
  textGroup.add(captionMesh);

  root.add(textGroup);

  // ---------- PARTICLES ----------
  const PARTICLE_COUNT_TOTAL = 1200;
  const CORE_COUNT = 90;
  const FIELD_COUNT = PARTICLE_COUNT_TOTAL - CORE_COUNT;

  const geometry = new THREE.IcosahedronGeometry(0.012, 0);

  // ---------- FIELD PARTICLES ----------
  const fieldMaterial = new NodeMaterial();
  fieldMaterial.colorNode = new THREE.Color('#e8ecf2');
  fieldMaterial.metalnessNode = 0.0;
  fieldMaterial.roughnessNode = 1.0;
  fieldMaterial.emissiveNode = new THREE.Color('#e8ecf2');
  fieldMaterial.emissiveIntensityNode = 0.9;
  fieldMaterial.transparent = true;
  fieldMaterial.opacityNode = new AttributeNode('instanceOpacity', 'float');
  fieldMaterial.side = THREE.DoubleSide;
  fieldMaterial.depthWrite = false;

  const fieldInst = new THREE.InstancedMesh(geometry, fieldMaterial, FIELD_COUNT);
  fieldInst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  // per‑instance buffers
  const fieldAnchorArray = new Float32Array(FIELD_COUNT * 3);
  const fieldOpacityArray = new Float32Array(FIELD_COUNT);
  const fieldPhaseArray = new Float32Array(FIELD_COUNT);

  const ellipsoidRadii = new THREE.Vector3(3, 2, 2.5); // half‑sizes of 6×4×5
  const ellipsoidCenter = new THREE.Vector3(0, 0, -1.5);

  for (let i = 0; i < FIELD_COUNT; i++) {
    // random point inside ellipsoid
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2.0 * Math.PI;
    const phi = Math.acos(2.0 * v - 1.0);
    const r = Math.cbrt(Math.random()); // uniform inside sphere, then scale

    const x = r * Math.sin(phi) * Math.cos(theta) * ellipsoidRadii.x;
    const y = r * Math.sin(phi) * Math.sin(theta) * ellipsoidRadii.y;
    const z = r * Math.cos(phi) * ellipsoidRadii.z;

    const pos = new THREE.Vector3().addVectors(ellipsoidCenter, new THREE.Vector3(x, y, z));

    // store anchor
    fieldAnchorArray[i * 3] = pos.x;
    fieldAnchorArray[i * 3 + 1] = pos.y;
    fieldAnchorArray[i * 3 + 2] = pos.z;

    // opacity based on depth (z)
    const opacity = THREE.MathUtils.lerp(0.9, 0.15, (0 - pos.z) / 5);
    fieldOpacityArray[i] = opacity;

    // random phase for drift
    fieldPhaseArray[i] = Math.random() * Math.PI * 2;

    const matrix = new THREE.Matrix4().setPosition(pos);
    fieldInst.setMatrixAt(i, matrix);
  }
  fieldInst.instanceMatrix.needsUpdate = true;
  fieldInst.geometry.setAttribute('instanceAnchor', new THREE.InstancedBufferAttribute(fieldAnchorArray, 3));
  fieldInst.geometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(fieldOpacityArray, 1));
  fieldInst.geometry.setAttribute('instancePhase', new THREE.InstancedBufferAttribute(fieldPhaseArray, 1));

  // ---------- CORE PARTICLES ----------
  const coreMaterial = new NodeMaterial();
  coreMaterial.colorNode = new THREE.Color('#ff2a38');
  coreMaterial.metalnessNode = 0.0;
  coreMaterial.roughnessNode = 1.0;
  coreMaterial.emissiveNode = new THREE.Color('#ff2a38');
  coreMaterial.emissiveIntensityNode = 1.5; // start value, will pulse
  coreMaterial.transparent = true;
  coreMaterial.blending = THREE.AdditiveBlending;
  coreMaterial.depthWrite = false;
  coreMaterial.side = THREE.DoubleSide;

  const coreInst = new THREE.InstancedMesh(geometry, coreMaterial, CORE_COUNT);
  coreInst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  const coreAnchorArray = new Float32Array(CORE_COUNT * 3);
  const coreOpacityArray = new Float32Array(CORE_COUNT);
  const corePhaseArray = new Float32Array(CORE_COUNT);

  for (let i = 0; i < CORE_COUNT; i++) {
    const phi = Math.acos(2.0 * Math.random() - 1.0);
    const theta = Math.random() * 2.0 * Math.PI;
    const r = Math.cbrt(Math.random()) * 0.5; // inside sphere radius 0.5

    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);

    const pos = new THREE.Vector3(x, y, z);

    coreAnchorArray[i * 3] = pos.x;
    coreAnchorArray[i * 3 + 1] = pos.y;
    coreAnchorArray[i * 3 + 2] = pos.z;

    // opacity for core (use same depth formula for consistency)
    const opacity = THREE.MathUtils.lerp(0.9, 0.15, (0 - (pos.z - 1.5)) / 5);
    coreOpacityArray[i] = opacity;

    corePhaseArray[i] = Math.random() * Math.PI * 2;

    const matrix = new THREE.Matrix4().setPosition(pos);
    coreInst.setMatrixAt(i, matrix);
  }
  coreInst.instanceMatrix.needsUpdate = true;
  coreInst.geometry.setAttribute('instanceAnchor', new THREE.InstancedBufferAttribute(coreAnchorArray, 3));
  coreInst.geometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(coreOpacityArray, 1));
  coreInst.geometry.setAttribute('instancePhase', new THREE.InstancedBufferAttribute(corePhaseArray, 1));

  // ---------- PARTICLE GROUP ----------
  const particlesGroup = new THREE.Group();
  particlesGroup.add(fieldInst);
  particlesGroup.add(coreInst);
  root.add(particlesGroup);

  // ---------- APPLY CINEMATIC PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(particlesGroup, prim.params);
      }
    }
  }

  // ---------- ANIMATIONS ----------
  const timelines = [];
  const tickerCallbacks = [];

  // Core pulsate (0.1 Hz → 10 s period, 5 s up, 5 s down)
  const corePulse = gsap.to(coreMaterial, {
    emissiveIntensity: 1.8,
    duration: 5,
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut',
  });
  timelines.push(corePulse);

  // Ambient drift – update matrices each tick
  const driftSpeed = 0.05; // Hz
  const driftAmplitude = 0.04; // units

  const driftCallback = (time) => {
    const t = time; // seconds from gsap ticker

    // Field particles
    const fieldMat = fieldInst.geometry.attributes.instanceAnchor;
    const fieldPhase = fieldInst.geometry.attributes.instancePhase;
    const fieldMatrix = new THREE.Matrix4();

    for (let i = 0; i < FIELD_COUNT; i++) {
      const ix = i * 3;
      const anchor = new THREE.Vector3(
        fieldAnchorArray[ix],
        fieldAnchorArray[ix + 1],
        fieldAnchorArray[ix + 2]
      );
      const phase = fieldPhaseArray[i];
      const offset = Math.sin(2.0 * Math.PI * driftSpeed * t + phase) * driftAmplitude;
      const pos = anchor.clone().addScalar(offset);
      fieldMatrix.setPosition(pos);
      fieldInst.setMatrixAt(i, fieldMatrix);
    }
    fieldInst.instanceMatrix.needsUpdate = true;

    // Core particles
    const coreMat = coreInst.geometry.attributes.instanceAnchor;
    const corePhase = coreInst.geometry.attributes.instancePhase;

    for (let i = 0; i < CORE_COUNT; i++) {
      const ix = i * 3;
      const anchor = new THREE.Vector3(
        coreAnchorArray[ix],
        coreAnchorArray[ix + 1],
        coreAnchorArray[ix + 2]
      );
      const phase = corePhaseArray[i];
      const offset = Math.sin(2.0 * Math.PI * driftSpeed * t + phase) * driftAmplitude;
      const pos = anchor.clone().addScalar(offset);
      coreMatrix.setPosition(pos);
      coreInst.setMatrixAt(i, coreMatrix);
    }
    coreInst.instanceMatrix.needsUpdate = true;
  };
  gsap.ticker.add(driftCallback);
  tickerCallbacks.push(driftCallback);

  // ---------- USER DATA ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose field particles
    fieldInst.geometry.dispose();
    fieldMaterial.dispose();

    // Dispose core particles
    coreInst.geometry.dispose();
    coreMaterial.dispose();

    // Dispose text meshes (assuming fontAtlas creates disposable materials)
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        obj.material?.dispose?.();
      }
    });

    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }

    // Remove ticker callbacks
    for (const cb of tickerCallbacks) {
      gsap.ticker.remove(cb);
    }

    // Remove any primitives that attached listeners (if they expose a dispose method)
    // Not required by spec, but safe:
    if (particlesGroup.userData?.dispose) {
      particlesGroup.userData.dispose();
    }
  };

  return root;
}
